from solution import number_of_substrings


def test_issue_example_abc():
    """Example from issue: number_of_substrings("abc") == 6."""
    assert number_of_substrings("abc") == 6  # 3*4/2 = 6


def test_issue_empty_string():
    """Empty string has zero non-empty substrings."""
    assert number_of_substrings("") == 0  # 0*1/2 = 0


def test_issue_single_character():
    """A single character has exactly one non-empty substring."""
    assert number_of_substrings("x") == 1  # 1*2/2 = 1


def test_issue_two_characters():
    """Two characters have three non-empty substrings."""
    assert number_of_substrings("ab") == 3  # 2*3/2 = 3


def test_issue_five_characters():
    """Five characters have fifteen non-empty substrings."""
    assert number_of_substrings("abcde") == 15  # 5*6/2 = 15


def test_issue_repeated_characters_counted_separately():
    """Repeated characters are counted by position, so "aaa" has six substrings."""
    assert number_of_substrings("aaa") == 6  # 3*4/2 = 6


def test_issue_overlapping_pattern():
    """Overlapping pattern "aba" still has six non-empty substrings."""
    assert number_of_substrings("aba") == 6  # 3*4/2 = 6


def test_issue_ten_characters():
    """Ten characters have fifty-five non-empty substrings."""
    assert number_of_substrings("abcdefghij") == 55  # 10*11/2 = 55


def test_contract_empty_substring_not_counted():
    """Contract: only non-empty substrings are counted, so length 6 gives 21 not 22."""
    assert number_of_substrings("abcdef") == 21  # 6*7/2 = 21


def test_contract_count_depends_only_on_length():
    """Contract: count depends only on length, so "wxyz" matches "abcd"."""
    assert number_of_substrings("wxyz") == 10  # 4*5/2 = 10


def test_contract_result_is_integer():
    """Contract: the count is returned as an integer."""
    assert isinstance(number_of_substrings("abc"), int)  # 3*4/2 = 6, must be int
